widget.solution:
def split_counts(X, y, feature, threshold):
    left = [0, 0]    # [repaid, default], value <= threshold
    right = [0, 0]   # [repaid, default], value > threshold
    for row, label in zip(X, y):
        if row[feature] <= threshold:
            left[label] += 1
        else:
            right[label] += 1
    return left, right
